[MethodImpl(MethodImplOptions.AggressiveInlining)]
private static (int wordIndex, ulong mask) WordMask(int bitIndex)
{
    int wordIndex = bitIndex >> 6;   // [0, 31] (32 ulong words in 256 bytes)
    bitIndex &= 63;                  // [0, 63] within each word
    int shift = bitIndex ^ mirrorMask;
    ulong mask = 1UL << shift;
    return (wordIndex, mask);
}

// PRIMARY: src/Nethermind/Nethermind.Core/Bloom.cs:WordMask (lines 201-213)
[MethodImpl(MethodImplOptions.AggressiveInlining)]
private static (int wordIndex, ulong mask) WordMask(int bitIndex)
{
    // bitIndex in [0, 2047]
    // wordIndex = bitIndex >> 6 = bitIndex / 64 -> [0, 31] (32 ulong words)
    // Each ulong = 8 bytes, so byte_index = wordIndex * 8 + offset -> [0, 255]
    int wordIndex = bitIndex >> 6;
    bitIndex &= 63;
    int shift = bitIndex ^ mirrorMask;
    ulong mask = 1UL << shift;
    return (wordIndex, mask);
    // wordIndex [0,31] maps to bytes [0,255] via 8-byte ulong alignment
}

